CodeInjections.CodeInjection:
    float2 normalTexCoords : TEXCOORDn;
    float2 glossmapTexCoords : TEXCOORDn;
    float3 coatObjPos : TEXCOORDn; // our addition: the undeformed body position, for spots made in the shader
#if defined(DIRT_SECONDUV) || defined(ALPHA_MAP_SECONDUV)
    float2 customTexCoords2 : TEXCOORDn;
#endif

/*
    XY - scale the texture (horizontal/vertical)
    4x2 texture = 0.25/0.5
    ZW - offset uv incorporated into scale
    4x2 texture = (0,1,2,3)/(0,1) or (0,-1,-2,-3)/(0,-1)
*/
float4 mirrorScaleAndOffsetUV;
/*
    XY - invert size of the atlas (horizontal/vertical)
    4x2 texture = 0.25/0.5
    ZW - offset uv after XY applied (horizontal/vertical)
    4x2 texture = (0.0,0.25,0.5,0.75)/(0.0,0.5)
*/
float4 atlasInvSizeAndOffsetUV;
/* our additions: coatTint rgb multiplies the coat; coatShade x brightness y saturation w eye gloss; patternA rgb colour a strength */
float4 coatTint;
float4 coatShade;
float4 patternA;
float4 markWhite;
float4 marks;
float4 flecks;
float4 spots;
#if defined( DIRT_ENABLED )
/*
    X - dirt amount 0..1
    YZ - dirtNmap uv scale
*/
    float3 dirt;
    float4 dirtColor; // color of the dirt
#endif
#if defined( SUBSURFACE_SCATTERING )
    float4 sssColor; // color of the fake subsurface scattering 
#endif

    float4 gGloss;
    float4 gCoatMask; // R coat, G eyeball, B hoof, A pattern A (1 0 0 0 without the mask)
    float4 gCoatMask2; // R spot field, G blanket gradient, B face levels, A sock gradient
#if defined( DIRT_ENABLED )
    float  gDirt;
#endif
#if defined( SUBSURFACE_SCATTERING )
    float gThickness;
    float gAlpha;
#endif

#if defined(DIRT_SECONDUV) || defined(ALPHA_MAP_SECONDUV) || defined(NORMAL_MAP_SECONDUV)
    // Pass second UVSet to the Pixel Shader
    Out.customTexCoords2 = convertDefaultTexCoords(In, object, In.texCoords1.xy);
#endif
    float2 newUV = getDefaultTexCoords(In, instance, object);
#if defined(NORMAL_MAP_SECONDUV)
    Out.normalTexCoords = Out.customTexCoords2;
#else
    // default behavior
    Out.normalTexCoords = newUV;
#endif
    Out.glossmapTexCoords = newUV;
    Out.coatObjPos = In.position.xyz;
    // mirror
    newUV = ((newUV-object.mirrorScaleAndOffsetUV.zw)*object.mirrorScaleAndOffsetUV.xy)+object.mirrorScaleAndOffsetUV.zw;
    // atlas
    newUV = newUV*object.atlasInvSizeAndOffsetUV.xy + object.atlasInvSizeAndOffsetUV.zw;
    Out.defaultTexCoords = newUV.xy;

globals.gGloss = float4(0.0,1.0,0.0,0.0);
#if defined( COAT_MASK )
    globals.gCoatMask = tex2DSample( coatMask, standardMaterialSampler, In.vs.glossmapTexCoords ).rgba;
    globals.gCoatMask2 = tex2DSample( coatMask2, standardMaterialSampler, In.vs.glossmapTexCoords ).rgba;
#else
    globals.gCoatMask = float4(1.0,0.0,0.0,0.0);
    globals.gCoatMask2 = float4(0.0,0.0,0.0,0.0);
#endif
#if defined( GLOSS_MAP )
    globals.gGloss = tex2DSample( glossMap, GLOSS_MAP_SAMPLER, In.vs.glossmapTexCoords).rgba;
#endif
#if defined( DIRT_ENABLED )
    #if defined( GLOSS_MAP )
        float texDirt  = 1 - globals.gGloss.b;
        #if defined(DIRT_SECONDUV)
            texDirt = 1 - tex2DSample( glossMap, GLOSS_MAP_SAMPLER, In.vs.customTexCoords2).b;
        #endif
        globals.gDirt  = saturate( (texDirt*1.05 - (object.dirt.x - 0.5)) * 2 );
    #else
        globals.gDirt = 1;
    #endif
#endif
#if defined( SUBSURFACE_SCATTERING )
    globals.gAlpha = 1.0;
    #if defined( GLOSS_MAP )
        globals.gThickness = globals.gGloss.a;
    #else
        globals.gThickness = 0.0;
    #endif
#endif

#if defined( DIRT_ENABLED )
    #if defined( NORMAL_MAP )
        float3 mNormal;
        #ifdef NORMAL_MAP_SIGNED_2CHANNEL
            // use BC5 signed format for the normal map
            mNormal.xy = tex2DSample(normalMap, NORMAL_MAP_SAMPLER, NORMAL_MAP_TEXCOORDS).xy;
            mNormal.z = sqrt(1.0 - dot(mNormal.xy, mNormal.xy));
        #else
            mNormal = tex2DSample(normalMap, NORMAL_MAP_SAMPLER, NORMAL_MAP_TEXCOORDS).xyz - 0.5;
        #endif
        float3 mDirtNmap = tex2DSample( dirtNmap, NORMAL_MAP_SAMPLER, float2( object.dirt.y, object.dirt.z ) * NORMAL_MAP_TEXCOORDS ).xyz - 0.5;
        return mNormal + float3(mDirtNmap.xy, 0.0) * (1 - globals.gDirt);
    #endif
#endif

    {   // our additions: the coat colour of this animal, then its pattern
        // the fur of the base coat (each texel's brightness against the coarse average round it) is carried into the white of the markings and the pinto patches: a flat white looked like spray paint
        float furDetail = 1.0;
#if defined( COAT_MASK )
        {
            float3 furCoarse = tex2DSampleLod( baseMap, standardMaterialSampler, In.vs.glossmapTexCoords, 4.0 ).rgb;
            float furRatio = dot(diffuseColor, float3(0.299, 0.587, 0.114)) / max(dot(furCoarse, float3(0.299, 0.587, 0.114)), 0.02);
            furDetail = lerp(1.0, clamp(furRatio, 0.55, 1.5), object.markWhite.a);   // markWhite.a: how much of the base coat's fur shows through the white (0 = flat white, the default; hdCoat fur 0..1)
        }
#endif
        float3 shaded = diffuseColor * object.coatTint.rgb;
        float shadeLum = dot(shaded, float3(0.299, 0.587, 0.114));
        shaded = lerp(float3(shadeLum, shadeLum, shadeLum), shaded, object.coatShade.y) * object.coatShade.x;
        diffuseColor = lerp(diffuseColor, shaded, globals.gCoatMask.r);
        diffuseColor = lerp(diffuseColor, object.patternA.rgb * furDetail, globals.gCoatMask.a * object.patternA.a);
        // markings (coatMask2): blanket with dark spots, white flecks, face marking, socks
        float4 m2 = globals.gCoatMask2;
        float blanketT = lerp(1.02, -0.05, object.marks.z);
        float blanket = smoothstep(blanketT - 0.03, blanketT + 0.03, m2.g) * step(0.001, object.marks.z);
        float dots = 0.0;
        if (object.flecks.x > 0.001 || object.marks.w > 0.001)
        {   // spots made in the shader (no texture detail to lose at a distance): jittered points in a 3D grid of object.spots.w metres, 2x2x2 cells around the pixel, a disc of random size at each; the mask's R says where
            // they may be (density: none on the muzzle and lids). A spot is never smaller than a pixel (spotPixel, in cells) and only as many are kept as keep the total white the same: far away they are single pixels, not vanished.
            float3 spotQ = In.vs.coatObjPos / object.spots.w - 0.5;
            float3 spotBase = floor(spotQ);
            float spotCov = 0.0;
            float spotPixel = max(length(ddx(In.vs.coatObjPos)), length(ddy(In.vs.coatObjPos))) / object.spots.w;
            {   // cell 0
                float3 spotS0 = spotBase + float3(0.0, 0.0, 0.0) + object.spots.z * 7.31;
                float spotH0 = frac(sin(dot(spotS0, float3(12.9898, 78.233, 37.719))) * 43758.5453);
                float spotH1 = frac(sin(dot(spotS0, float3(39.346, 11.135, 83.155))) * 24634.6345);
                float spotH2 = frac(sin(dot(spotS0, float3(73.156, 52.235, 9.151))) * 31415.9265);
                float spotH3 = frac(sin(dot(spotS0, float3(27.623, 63.451, 21.917))) * 17453.2925);
                float spotH4 = frac(sin(dot(spotS0, float3(51.771, 17.337, 66.209))) * 28571.4285);
                float spotH5 = frac(sin(dot(spotS0, float3(18.231, 44.917, 73.403))) * 36542.7311);
                float3 spotPt = spotBase + float3(0.5, 0.5, 0.5) + (float3(spotH0, spotH1, spotH2) - 0.5) * 0.4;
                float spotRad = (0.10 + 0.18 * spotH3) * object.spots.y;
                float spotRadE = (object.flecks.w > 0.5) ? spotRad : max(spotRad, object.flecks.y * spotPixel);   // never smaller than flecks.y pixels in radius (default 2: TAA averages away anything under about 3 px across): far away a spot is a small dot, not nothing ...
                float spotKeep = (object.flecks.w > 0.5) ? 1.0 : step(spotH5, max((spotRad * spotRad) / (spotRadE * spotRadE), 0.45));   // ... and fewer are kept as they grow (the white's total stays the same) but never fewer than 45 percent: a sparse pattern must still read at a distance (overstated on purpose)
                float spotD = length(spotQ + 0.5 - spotPt);
                spotCov = max(spotCov, step(spotH4, object.spots.x * m2.r) * spotKeep * saturate((spotRadE - spotD) / ((object.flecks.w > 0.5) ? 0.35 * spotRadE : max(0.35 * spotRadE, 0.5 * spotPixel))));
            }
            {   // cell 1
                float3 spotS1 = spotBase + float3(1.0, 0.0, 0.0) + object.spots.z * 7.31;
                float spotH0 = frac(sin(dot(spotS1, float3(12.9898, 78.233, 37.719))) * 43758.5453);
                float spotH1 = frac(sin(dot(spotS1, float3(39.346, 11.135, 83.155))) * 24634.6345);
                float spotH2 = frac(sin(dot(spotS1, float3(73.156, 52.235, 9.151))) * 31415.9265);
                float spotH3 = frac(sin(dot(spotS1, float3(27.623, 63.451, 21.917))) * 17453.2925);
                float spotH4 = frac(sin(dot(spotS1, float3(51.771, 17.337, 66.209))) * 28571.4285);
                float spotH5 = frac(sin(dot(spotS1, float3(18.231, 44.917, 73.403))) * 36542.7311);
                float3 spotPt = spotBase + float3(1.5, 0.5, 0.5) + (float3(spotH0, spotH1, spotH2) - 0.5) * 0.4;
                float spotRad = (0.10 + 0.18 * spotH3) * object.spots.y;
                float spotRadE = (object.flecks.w > 0.5) ? spotRad : max(spotRad, object.flecks.y * spotPixel);   // never smaller than flecks.y pixels in radius (default 2: TAA averages away anything under about 3 px across): far away a spot is a small dot, not nothing ...
                float spotKeep = (object.flecks.w > 0.5) ? 1.0 : step(spotH5, max((spotRad * spotRad) / (spotRadE * spotRadE), 0.45));   // ... and fewer are kept as they grow (the white's total stays the same) but never fewer than 45 percent: a sparse pattern must still read at a distance (overstated on purpose)
                float spotD = length(spotQ + 0.5 - spotPt);
                spotCov = max(spotCov, step(spotH4, object.spots.x * m2.r) * spotKeep * saturate((spotRadE - spotD) / ((object.flecks.w > 0.5) ? 0.35 * spotRadE : max(0.35 * spotRadE, 0.5 * spotPixel))));
            }
            {   // cell 2
                float3 spotS2 = spotBase + float3(0.0, 1.0, 0.0) + object.spots.z * 7.31;
                float spotH0 = frac(sin(dot(spotS2, float3(12.9898, 78.233, 37.719))) * 43758.5453);
                float spotH1 = frac(sin(dot(spotS2, float3(39.346, 11.135, 83.155))) * 24634.6345);
                float spotH2 = frac(sin(dot(spotS2, float3(73.156, 52.235, 9.151))) * 31415.9265);
                float spotH3 = frac(sin(dot(spotS2, float3(27.623, 63.451, 21.917))) * 17453.2925);
                float spotH4 = frac(sin(dot(spotS2, float3(51.771, 17.337, 66.209))) * 28571.4285);
                float spotH5 = frac(sin(dot(spotS2, float3(18.231, 44.917, 73.403))) * 36542.7311);
                float3 spotPt = spotBase + float3(0.5, 1.5, 0.5) + (float3(spotH0, spotH1, spotH2) - 0.5) * 0.4;
                float spotRad = (0.10 + 0.18 * spotH3) * object.spots.y;
                float spotRadE = (object.flecks.w > 0.5) ? spotRad : max(spotRad, object.flecks.y * spotPixel);   // never smaller than flecks.y pixels in radius (default 2: TAA averages away anything under about 3 px across): far away a spot is a small dot, not nothing ...
                float spotKeep = (object.flecks.w > 0.5) ? 1.0 : step(spotH5, max((spotRad * spotRad) / (spotRadE * spotRadE), 0.45));   // ... and fewer are kept as they grow (the white's total stays the same) but never fewer than 45 percent: a sparse pattern must still read at a distance (overstated on purpose)
                float spotD = length(spotQ + 0.5 - spotPt);
                spotCov = max(spotCov, step(spotH4, object.spots.x * m2.r) * spotKeep * saturate((spotRadE - spotD) / ((object.flecks.w > 0.5) ? 0.35 * spotRadE : max(0.35 * spotRadE, 0.5 * spotPixel))));
            }
            {   // cell 3
                float3 spotS3 = spotBase + float3(1.0, 1.0, 0.0) + object.spots.z * 7.31;
                float spotH0 = frac(sin(dot(spotS3, float3(12.9898, 78.233, 37.719))) * 43758.5453);
                float spotH1 = frac(sin(dot(spotS3, float3(39.346, 11.135, 83.155))) * 24634.6345);
                float spotH2 = frac(sin(dot(spotS3, float3(73.156, 52.235, 9.151))) * 31415.9265);
                float spotH3 = frac(sin(dot(spotS3, float3(27.623, 63.451, 21.917))) * 17453.2925);
                float spotH4 = frac(sin(dot(spotS3, float3(51.771, 17.337, 66.209))) * 28571.4285);
                float spotH5 = frac(sin(dot(spotS3, float3(18.231, 44.917, 73.403))) * 36542.7311);
                float3 spotPt = spotBase + float3(1.5, 1.5, 0.5) + (float3(spotH0, spotH1, spotH2) - 0.5) * 0.4;
                float spotRad = (0.10 + 0.18 * spotH3) * object.spots.y;
                float spotRadE = (object.flecks.w > 0.5) ? spotRad : max(spotRad, object.flecks.y * spotPixel);   // never smaller than flecks.y pixels in radius (default 2: TAA averages away anything under about 3 px across): far away a spot is a small dot, not nothing ...
                float spotKeep = (object.flecks.w > 0.5) ? 1.0 : step(spotH5, max((spotRad * spotRad) / (spotRadE * spotRadE), 0.45));   // ... and fewer are kept as they grow (the white's total stays the same) but never fewer than 45 percent: a sparse pattern must still read at a distance (overstated on purpose)
                float spotD = length(spotQ + 0.5 - spotPt);
                spotCov = max(spotCov, step(spotH4, object.spots.x * m2.r) * spotKeep * saturate((spotRadE - spotD) / ((object.flecks.w > 0.5) ? 0.35 * spotRadE : max(0.35 * spotRadE, 0.5 * spotPixel))));
            }
            {   // cell 4
                float3 spotS4 = spotBase + float3(0.0, 0.0, 1.0) + object.spots.z * 7.31;
                float spotH0 = frac(sin(dot(spotS4, float3(12.9898, 78.233, 37.719))) * 43758.5453);
                float spotH1 = frac(sin(dot(spotS4, float3(39.346, 11.135, 83.155))) * 24634.6345);
                float spotH2 = frac(sin(dot(spotS4, float3(73.156, 52.235, 9.151))) * 31415.9265);
                float spotH3 = frac(sin(dot(spotS4, float3(27.623, 63.451, 21.917))) * 17453.2925);
                float spotH4 = frac(sin(dot(spotS4, float3(51.771, 17.337, 66.209))) * 28571.4285);
                float spotH5 = frac(sin(dot(spotS4, float3(18.231, 44.917, 73.403))) * 36542.7311);
                float3 spotPt = spotBase + float3(0.5, 0.5, 1.5) + (float3(spotH0, spotH1, spotH2) - 0.5) * 0.4;
                float spotRad = (0.10 + 0.18 * spotH3) * object.spots.y;
                float spotRadE = (object.flecks.w > 0.5) ? spotRad : max(spotRad, object.flecks.y * spotPixel);   // never smaller than flecks.y pixels in radius (default 2: TAA averages away anything under about 3 px across): far away a spot is a small dot, not nothing ...
                float spotKeep = (object.flecks.w > 0.5) ? 1.0 : step(spotH5, max((spotRad * spotRad) / (spotRadE * spotRadE), 0.45));   // ... and fewer are kept as they grow (the white's total stays the same) but never fewer than 45 percent: a sparse pattern must still read at a distance (overstated on purpose)
                float spotD = length(spotQ + 0.5 - spotPt);
                spotCov = max(spotCov, step(spotH4, object.spots.x * m2.r) * spotKeep * saturate((spotRadE - spotD) / ((object.flecks.w > 0.5) ? 0.35 * spotRadE : max(0.35 * spotRadE, 0.5 * spotPixel))));
            }
            {   // cell 5
                float3 spotS5 = spotBase + float3(1.0, 0.0, 1.0) + object.spots.z * 7.31;
                float spotH0 = frac(sin(dot(spotS5, float3(12.9898, 78.233, 37.719))) * 43758.5453);
                float spotH1 = frac(sin(dot(spotS5, float3(39.346, 11.135, 83.155))) * 24634.6345);
                float spotH2 = frac(sin(dot(spotS5, float3(73.156, 52.235, 9.151))) * 31415.9265);
                float spotH3 = frac(sin(dot(spotS5, float3(27.623, 63.451, 21.917))) * 17453.2925);
                float spotH4 = frac(sin(dot(spotS5, float3(51.771, 17.337, 66.209))) * 28571.4285);
                float spotH5 = frac(sin(dot(spotS5, float3(18.231, 44.917, 73.403))) * 36542.7311);
                float3 spotPt = spotBase + float3(1.5, 0.5, 1.5) + (float3(spotH0, spotH1, spotH2) - 0.5) * 0.4;
                float spotRad = (0.10 + 0.18 * spotH3) * object.spots.y;
                float spotRadE = (object.flecks.w > 0.5) ? spotRad : max(spotRad, object.flecks.y * spotPixel);   // never smaller than flecks.y pixels in radius (default 2: TAA averages away anything under about 3 px across): far away a spot is a small dot, not nothing ...
                float spotKeep = (object.flecks.w > 0.5) ? 1.0 : step(spotH5, max((spotRad * spotRad) / (spotRadE * spotRadE), 0.45));   // ... and fewer are kept as they grow (the white's total stays the same) but never fewer than 45 percent: a sparse pattern must still read at a distance (overstated on purpose)
                float spotD = length(spotQ + 0.5 - spotPt);
                spotCov = max(spotCov, step(spotH4, object.spots.x * m2.r) * spotKeep * saturate((spotRadE - spotD) / ((object.flecks.w > 0.5) ? 0.35 * spotRadE : max(0.35 * spotRadE, 0.5 * spotPixel))));
            }
            {   // cell 6
                float3 spotS6 = spotBase + float3(0.0, 1.0, 1.0) + object.spots.z * 7.31;
                float spotH0 = frac(sin(dot(spotS6, float3(12.9898, 78.233, 37.719))) * 43758.5453);
                float spotH1 = frac(sin(dot(spotS6, float3(39.346, 11.135, 83.155))) * 24634.6345);
                float spotH2 = frac(sin(dot(spotS6, float3(73.156, 52.235, 9.151))) * 31415.9265);
                float spotH3 = frac(sin(dot(spotS6, float3(27.623, 63.451, 21.917))) * 17453.2925);
                float spotH4 = frac(sin(dot(spotS6, float3(51.771, 17.337, 66.209))) * 28571.4285);
                float spotH5 = frac(sin(dot(spotS6, float3(18.231, 44.917, 73.403))) * 36542.7311);
                float3 spotPt = spotBase + float3(0.5, 1.5, 1.5) + (float3(spotH0, spotH1, spotH2) - 0.5) * 0.4;
                float spotRad = (0.10 + 0.18 * spotH3) * object.spots.y;
                float spotRadE = (object.flecks.w > 0.5) ? spotRad : max(spotRad, object.flecks.y * spotPixel);   // never smaller than flecks.y pixels in radius (default 2: TAA averages away anything under about 3 px across): far away a spot is a small dot, not nothing ...
                float spotKeep = (object.flecks.w > 0.5) ? 1.0 : step(spotH5, max((spotRad * spotRad) / (spotRadE * spotRadE), 0.45));   // ... and fewer are kept as they grow (the white's total stays the same) but never fewer than 45 percent: a sparse pattern must still read at a distance (overstated on purpose)
                float spotD = length(spotQ + 0.5 - spotPt);
                spotCov = max(spotCov, step(spotH4, object.spots.x * m2.r) * spotKeep * saturate((spotRadE - spotD) / ((object.flecks.w > 0.5) ? 0.35 * spotRadE : max(0.35 * spotRadE, 0.5 * spotPixel))));
            }
            {   // cell 7
                float3 spotS7 = spotBase + float3(1.0, 1.0, 1.0) + object.spots.z * 7.31;
                float spotH0 = frac(sin(dot(spotS7, float3(12.9898, 78.233, 37.719))) * 43758.5453);
                float spotH1 = frac(sin(dot(spotS7, float3(39.346, 11.135, 83.155))) * 24634.6345);
                float spotH2 = frac(sin(dot(spotS7, float3(73.156, 52.235, 9.151))) * 31415.9265);
                float spotH3 = frac(sin(dot(spotS7, float3(27.623, 63.451, 21.917))) * 17453.2925);
                float spotH4 = frac(sin(dot(spotS7, float3(51.771, 17.337, 66.209))) * 28571.4285);
                float spotH5 = frac(sin(dot(spotS7, float3(18.231, 44.917, 73.403))) * 36542.7311);
                float3 spotPt = spotBase + float3(1.5, 1.5, 1.5) + (float3(spotH0, spotH1, spotH2) - 0.5) * 0.4;
                float spotRad = (0.10 + 0.18 * spotH3) * object.spots.y;
                float spotRadE = (object.flecks.w > 0.5) ? spotRad : max(spotRad, object.flecks.y * spotPixel);   // never smaller than flecks.y pixels in radius (default 2: TAA averages away anything under about 3 px across): far away a spot is a small dot, not nothing ...
                float spotKeep = (object.flecks.w > 0.5) ? 1.0 : step(spotH5, max((spotRad * spotRad) / (spotRadE * spotRadE), 0.45));   // ... and fewer are kept as they grow (the white's total stays the same) but never fewer than 45 percent: a sparse pattern must still read at a distance (overstated on purpose)
                float spotD = length(spotQ + 0.5 - spotPt);
                spotCov = max(spotCov, step(spotH4, object.spots.x * m2.r) * spotKeep * saturate((spotRadE - spotD) / ((object.flecks.w > 0.5) ? 0.35 * spotRadE : max(0.35 * spotRadE, 0.5 * spotPixel))));
            }
            dots = spotCov;
        }
        float whiteBlanket = blanket * (1.0 - dots * object.marks.w);
        float whiteFlecks = dots * object.flecks.x * (1.0 - blanket);
        float faceT = 1.1 - 0.7 * object.marks.x;
        float face = smoothstep(faceT - 0.05, faceT + 0.05, m2.b) * step(0.001, object.marks.x);
        float sockT = 1.0 - object.marks.y;
        float sock = smoothstep(sockT - 0.04, sockT + 0.04, m2.a) * smoothstep(0.0, 0.04, m2.a) * step(0.001, object.marks.y);   // (the second factor: no sock where the field is 0, else socks 1 whitens everything that is not a leg)
        float whiteAmount = max(max(whiteBlanket, whiteFlecks), max(face, sock)) * globals.gCoatMask.r;
        diffuseColor = lerp(diffuseColor, object.markWhite.rgb * furDetail, whiteAmount);
    }
#if defined( DIRT_ENABLED )
    #if defined( SPECULAR ) && defined( GLOSS_MAP )
        diffuseColor = lerp( object.dirtColor.rgb, diffuseColor, globals.gDirt); // DirtColor lerp
    #endif
#endif


 #if defined( SUBSURFACE_SCATTERING )
    float fLTAmbient =      0.15;
    float fLTPower =        2.0;
    float fLTDistortion =   1.0;
    float fLTScale =        2.0;

    float fLightAttenuation = saturate(dot(normal, lightDir)) + saturate(dot(viewDir, -lightDir));

    float3 vLTLight = lightDir + normal * fLTDistortion;
    float fLTDot = pow(saturate(dot(viewDir, -vLTLight)), fLTPower) * fLTScale;
    float fLT = fLightAttenuation * (fLTDot + fLTAmbient) * globals.gThickness;
    float3 cLT = diffuseColor * lightColor * fLT * object.sssColor.rgb;
    #if defined(ALPHA_BLENDED)
        cLT *= globals.gAlpha;
    #endif
    #if defined( DIRT_ENABLED )
        cLT *= clamp(globals.gDirt,0.4,1.0);
    #endif
    lighting.xyz += cLT * lightAtten;
    #if defined( DEBUG_SHOW_PARALLAX )
        lighting.xyz = cLT * lightAtten;
    #endif
#endif
#if defined( COAT_MASK )
    {   // our addition: the sun's glint on the eyeballs (viewDir and lightDir point away from the surface, as in the scattering above)
        float3 glintHalf = normalize(lightDir + viewDir);
        float glint = pow(saturate(dot(normal, glintHalf)), 500.0) * globals.gCoatMask.g * object.coatShade.w * 30.0;
        lighting.xyz += lightColor * glint * lightAtten;
    }
#endif

#if defined(ALPHA_TESTED) || defined(ALPHA_BLENDED)
    #if defined(ALBEDO_MAP)
        #if defined(ALPHA_MAP)
            alpha = tex2DSample(alphaMap, standardMaterialSampler, In.vs.glossmapTexCoords).x;
        #elif defined(ALPHA_MAP_SECONDUV)
            alpha = tex2DSample(alphaMap, standardMaterialSampler, In.vs.customTexCoords2).x;
        #else
            // Default Behaviour
            alpha = tex2DSample( baseMap, ALBEDO_MAP_SAMPLER, In.vs.glossmapTexCoords).a;
        #endif
    #endif
#endif
#if defined(ALPHA_BLENDED)
    reflectingLightingScale = alpha;
    #if defined( SUBSURFACE_SCATTERING )
        globals.gAlpha = alpha;
    #endif
#endif
